.ring svg { transform: rotate(-90deg); display: block; }
.ring-center { position: absolute; inset: 0; display: grid; place-items: center; text-align: center; }
.ring-center b { display: block; font-size: 24px; font-weight: 800; letter-spacing: -.02em; line-height: 1.15; }
.ring-center b span { font-size: inherit; color: inherit; }
.ring-center > div > span { display: block; font-size: 11px; color: var(--muted); margin-top: 2px; }
.breakdown { flex: 1; min-width: 220px; }
.stack { display: flex; height: 12px; border-radius: 8px; overflow: hidden; background: var(--soft); margin: 4px 0 12px; }
.stack div { height: 100%; width: 0; transition: width 1s cubic-bezier(.2, .8, .2, 1); }
.legend-rows div { display: flex; justify-content: space-between; gap: 8px; padding: 5px 0; border-bottom: 1px dashed var(--line); font-size: 12.5px; }
.legend-rows div:last-child { border-bottom: none; }
.legend-rows i { display: inline-block; width: 9px; height: 9px; border-radius: 3px; margin-right: 7px; }
.legend-rows b { font-variant-numeric: tabular-nums; }

/* ---------- bars ---------- */
.hbar { margin: 10px 0; }
.hbar-head { display: flex; justify-content: space-between; gap: 10px; font-size: 12.5px; }
.hbar-name { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.hbar-val { color: var(--muted); white-space: nowrap; font-variant-numeric: tabular-nums; }
.track { position: relative; height: 8px; border-radius: 6px; background: var(--soft); margin-top: 5px; overflow: hidden; }
.fill { position: absolute; left: 0; top: 0; bottom: 0; width: 0; border-radius: 6px; transition: width 1s cubic-bezier(.2, .8, .2, 1); }
.fill.ghost { opacity: .28; }
.hbar.link { cursor: pointer; }
.hbar.link:hover .hbar-name { color: var(--hero, #2f7ff0); }
.legend { display: flex; flex-wrap: wrap; gap: 12px; font-size: 11.5px; color: var(--muted); margin-top: 10px; }
.legend i { display: inline-block; width: 9px; height: 9px; border-radius: 3px; margin-right: 5px; vertical-align: -1px; }

/* ---------- donut ---------- */
.donut { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; }
.donut svg { flex: 0 0 auto; transform: rotate(-90deg); }
.donut circle.arc { transition: stroke-dasharray 1.1s cubic-bezier(.2, .8, .2, 1); }
.donut-wrap { position: relative; flex: 0 0 auto; }
.donut-list { flex: 1; min-width: 150px; font-size: 12.5px; }
.donut-list div { display: flex; justify-content: space-between; gap: 8px; padding: 4px 0; }
.donut-list i { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 7px; }
.donut-list b { font-variant-numeric: tabular-nums; }

/* ---------- column chart ---------- */
.cols { display: flex; align-items: flex-end; gap: 8px; height: 170px; padding-top: 6px; border-bottom: 1px solid var(--line); }
.col { flex: 1; height: 100%; display: flex; align-items: flex-end; justify-content: center; gap: 3px; min-width: 0; position: relative; }
.col-bar { flex: 1; max-width: 26px; border-radius: 6px 6px 2px 2px; height: 0; transition: height 1s cubic-bezier(.2, .8, .2, 1); display: flex; flex-direction: column-reverse; overflow: hidden; }
.col-bar > div { width: 100%; }
.col-labels { display: flex; gap: 8px; margin-top: 6px; }
.col-labels span { flex: 1; text-align: center; font-size: 10.5px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.col:hover .col-bar { filter: brightness(1.08); }

/* ---------- tabs + tables ---------- */
.tabs { display: flex; gap: 4px; padding: 3px; background: var(--soft); border-radius: 10px; margin-bottom: 12px; width: fit-content; max-width: 100%; overflow-x: auto; }
.tab { border: 0; background: transparent; color: var(--muted); padding: 6px 12px; border-radius: 8px; font-size: 12.5px; font-weight: 600; cursor: pointer; white-space: nowrap; transition: background .2s, color .2s; }
.tab.active { background: var(--card); color: var(--ink); box-shadow: 0 1px 3px rgba(16, 24, 40, .1); }
.tab .count { margin-left: 5px; font-size: 11px; padding: 0 6px; border-radius: 10px; background: color-mix(in srgb, var(--hero, #2f7ff0) 14%, transparent); color: var(--hero, #2f7ff0); }
.tab-pane { display: none; }
.tab-pane.active { display: block; animation: rise .35s ease both; }
.table-wrap { overflow: auto; max-height: 440px; border-radius: 10px; }
table.t { width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px; }
table.t th { position: sticky; top: 0; z-index: 1; background: var(--card); text-align: left; font-weight: 600; color: var(--muted); font-size: 11.5px;
    text-transform: uppercase; letter-spacing: .04em; border-bottom: 1px solid var(--line); padding: 9px 10px; white-space: nowrap; }
table.t td { border-bottom: 1px solid var(--line); padding: 9px 10px; vertical-align: middle; }
table.t tr:last-child td { border-bottom: none; }
table.t .num { text-align: right; white-space: nowrap; font-variant-numeric: tabular-nums; }
table.t tr.link { cursor: pointer; transition: background .15s; }
table.t tr.link:hover td { background: var(--soft); }
.sub { color: var(--muted); font-size: 11.5px; }
.pill { display: inline-block; padding: 2px 9px; border-radius: 20px; font-size: 11px; font-weight: 600; white-space: nowrap; }
.pill.green { background: color-mix(in srgb, var(--green) 13%, transparent); color: var(--green); }
.pill.orange { background: color-mix(in srgb, var(--orange) 15%, transparent); color: var(--orange); }
.pill.red { background: color-mix(in srgb, var(--red) 13%, transparent); color: var(--red); }
.pill.blue { background: color-mix(in srgb, var(--blue) 13%, transparent); color: var(--blue); }
.pill.gray { background: color-mix(in srgb, var(--slate) 15%, transparent); color: var(--slate); }
.mini { display: inline-block; width: 80px; height: 6px; border-radius: 4px; background: var(--soft); vertical-align: middle; margin-right: 7px; overflow: hidden; position: relative; }
.mini span { position: absolute; left: 0; top: 0; bottom: 0; width: 0; border-radius: 4px; transition: width 1s cubic-bezier(.2, .8, .2, 1); }
.list-row { display: flex; justify-content: space-between; align-items: center; gap: 10px; padding: 8px 0; border-bottom: 1px dashed var(--line); font-size: 12.5px; }
.list-row:last-child { border-bottom: none; }
.list-row.link { cursor: pointer; }
.list-row.link:hover b { color: var(--hero, #2f7ff0); }
.avatar { width: 28px; height: 28px; border-radius: 50%; display: inline-grid; place-items: center; font-size: 11px; font-weight: 700; color: #fff; margin-right: 9px; flex: 0 0 auto; }
.who { display: flex; align-items: center; min-width: 0; }
.who b { font-weight: 600; }

/* ---------- motion ---------- */
.anim { animation: rise .55s cubic-bezier(.2, .8, .2, 1) both; animation-delay: calc(var(--i, 0) * 45ms); }
@keyframes rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
@keyframes spin { to { transform: rotate(360deg); } }
